    pub os_template: String,
    pub swap_mb: u32,
    pub unprivileged: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct WarpConfig {
    pub enabled: bool,
    pub bridge_interface: String,
